CREATE POLICY "store images read" ON storage.objects FOR SELECT USING (bucket_id = 'store-images');
CREATE POLICY "store images admin insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'store-images' AND public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "store images admin update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'store-images' AND public.has_role(auth.uid(), 'admin'::public.app_role)) WITH CHECK (bucket_id = 'store-images' AND public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "store images admin delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'store-images' AND public.has_role(auth.uid(), 'admin'::public.app_role));